import httpStatus from "http-status";
import { catchAsync } from "utils/catchAsync";
import {
  acknowledgeRequest,
  createFriendRequest,
  findExistingRequest,
  findFriendRequestById,
  findFriendRequests,
  findFriends,
} from "../../services/friends.service";
import { isValidObjectId } from "mongoose";
import { EnumFriendRequest } from "../../models/enum.model";

export const fetchAllFriends = catchAsync(async (req, res) => {
  const pagination = req.query;
  const friends = await findFriends(req.user._id, pagination);

  res.status(httpStatus.OK).send({
    results: {
      success: true,
      message: "Friends fetched successfully.",
      friends,
    },
  });
});

export const sendFriendRequest = catchAsync(async (req, res) => {
  const { receiver } = req.body;
  const user = req.user;

  if (receiver === user._id.toString()) {
    return res.status(httpStatus.BAD_REQUEST).json({
      results: {
        success: false,
        message: "You can not send a request to yourself.",
      },
    });
  }

  const existingRequest = await findExistingRequest(receiver, user._id);

  if (existingRequest && existingRequest.status === EnumFriendRequest.PENDING) {
    return res.status(httpStatus.BAD_REQUEST).json({
      results: {
        success: false,
        message: "You already send a request. Please wait for their response.",
      },
    });
  }

  if (
    existingRequest &&
    existingRequest.status === EnumFriendRequest.ACCEPTED
  ) {
    return res.status(httpStatus.BAD_REQUEST).json({
      results: {
        success: false,
        message: "You are already friends.",
      },
    });
  }

  const friendRequest = await createFriendRequest({
    receiver,
    requester: user._id,
  });

  if (!friendRequest) {
    return res.status(httpStatus.BAD_REQUEST).send({
      results: {
        success: false,
        message: "Something went wrong please try again.",
      },
    });
  }

  res.status(httpStatus.OK).send({
    results: {
      success: true,
      message: "Request sent successfully.",
    },
  });
});

export const friendRequest = catchAsync(async (req, res) => {
  const requestId = req.params.id;
  const { status } = req.body;
  const user = req.user;

  if (!isValidObjectId(requestId)) {
    return res.status(httpStatus.BAD_REQUEST).send({
      results: {
        success: false,
        message: "Invalid request id.",
      },
    });
  }

  const existingFriendRequest = await findFriendRequestById(requestId);

  if (!existingFriendRequest) {
    return res.status(httpStatus.NOT_FOUND).send({
      results: {
        success: false,
        message: "Friend request not found.",
      },
    });
  }

  if (existingFriendRequest.receiver.toString() !== user._id.toString()) {
    return res.status(httpStatus.NOT_FOUND).send({
      results: {
        success: false,
        message: "You are not allowed to acknowledge this request.",
      },
    });
  }

  if (existingFriendRequest.status !== EnumFriendRequest.PENDING) {
    return res.status(httpStatus.NOT_FOUND).send({
      results: {
        success: false,
        message: "You already acknowledged this request.",
      },
    });
  }

  const response = await acknowledgeRequest(
    requestId,
    status ? EnumFriendRequest.ACCEPTED : EnumFriendRequest.REJECTED
  );

  if (!response) {
    return res.status(httpStatus.BAD_REQUEST).send({
      results: {
        success: false,
        message: "Something went wrong please try again.",
      },
    });
  }

  res.status(httpStatus.OK).send({
    results: {
      success: true,
      message: `Request ${status ? "accepted" : "declined"} successfully.`,
    },
  });
});

export const getFriendRequestWithPagination = catchAsync(async (req, res) => {
  const pagination = req.query;

  const friends = await findFriendRequests(req.user._id, pagination);

  res.status(httpStatus.OK).send({
    results: {
      success: true,
      message: "Friends requests fetched successfully.",
      friends,
    },
  });
});
